mapper.select:
select distinct capinfo.ACCT_NO acctNo, capinfo.BUSI_ACCT_NO busiAcctNo, capinfo.CCY CCY, capinfo.acct_name accountName, msd.inter_type acctType, capinfo.OWN_DEPT stockExchangeNo, '1' status, capinfo.ACC_PASS acctPwd, capinfo.TRADE_PASS tradePwd from STL_CAPACCT_INFO capinfo LEFT JOIN PTL_CAPACCT_INFO ptl ON capinfo.ACCT_NO=ptl.ACCT_NO left join mst_sale_department msd on msd.sale_depid=capinfo.OWN_DEPT
ptl.acct_type IN ('A07','B24')
and ptl.PORTFOLIO_ID =#{portfolioId,jdbcType=VARCHAR}
and capinfo.ACCT_NO =#{acctNo,jdbcType=VARCHAR}
and capinfo.BUSI_ACCT_NO =#{busiAcctNo,jdbcType=VARCHAR}
and msd.inter_type =#{acctType,jdbcType=VARCHAR}

    	select sum(count) from(
		 select count(*) count from MST_COUNTER_ACCT T1 ,STL_CAPACCT_INFO T2 
		 	where T1.ACCT_NO=T2.ACCT_NO 
		 		and T1.CCY=T2.CCY 
		 		and T2.ACCT_NO = #{acctNo,jdbcType=VARCHAR} 
		 		and T2.CCY = #{ccy,jdbcType=VARCHAR}
		 union all select count(*) count from STL_FIN_PRODUCT_ACCT T3 ,STL_CAPACCT_INFO T4 
		 	where T3.ACCT_NO=T4.ACCT_NO 
		 		and T3.CCY=T4.CCY 
		 		and T4.ACCT_NO = #{acctNo,jdbcType=VARCHAR} 
		 		and T4.CCY = #{ccy,jdbcType=VARCHAR}
		 union all select count(*) count from PTL_CAPACCT_INFO T5 ,STL_CAPACCT_INFO T6 
		 	where T5.ACCT_NO=T6.ACCT_NO 
		 		and T5.CCY=T6.CCY 
		 		and T6.ACCT_NO = #{acctNo,jdbcType=VARCHAR}
		 		and T6.CCY = #{ccy,jdbcType=VARCHAR}
		)

select
count(1)
from STL_CAPACCT_INFO


		AND	BUSI_ACCT_NO = #{busiAcctNo,jdbcType=VARCHAR}


		AND	LARGE_PAYNO = #{largePayno,jdbcType=VARCHAR}

SELECT 
	T1.INT_RATE
FROM  MST_INT_RATE_INFO T1
WHERE T1.INT_RATE_ID = #{indexId}
	AND T1.CCY = #{ccy}
	AND T1.EFF_DATE = 
		(SELECT 
			MAX(T2.EFF_DATE) 
			FROM 
				MST_INT_RATE_INFO T2 
			WHERE T2.INT_RATE_ID = #{indexId} 
				AND T2.CCY = #{ccy} 
				AND T2.EFF_DATE <= TO_DATE(#{effDate},'YYYY-MM-DD'))

select 
       rate.eff_date effectDate,
       rate.int_type rateType,
       rate.basis basis,
       case when rate.int_type = #{INT_TYPE_01}
         then rate.rate * 100
           else 0 end rate,
       case when rate.int_type = #{INT_TYPE_02}
         then rate.rate * 100 
           else 0 end currentRate,
       rate.coefficient coefficient,
       rate.spread_rate * 100 spreadRate,
       rate.benchmark_id indexId
  from fin_cash_info info
  left join fin_Rate_Info rate
    on rate.cash_id = info.cash_id
 where info.cash_type_1 = #{CASH_TYPE_1_02}
   and info.cash_type_2 = #{CASH_TYPE_2_C02}
   and info.finprod_type = #{FIN_CASH_BUSINESS_TYPE_02}
   and info.finprod_id = #{finprodId}
 order by rate.eff_date asc

